queries:
SELECT AVG(total_points), AVG(avg_laps) FROM (SELECT driverId, SUM(points) AS total_points, AVG(CAST(laps AS REAL)) AS avg_laps FROM results WHERE grid > 12 GROUP BY driverId)
SELECT AVG(points), AVG(CAST(laps AS REAL)) FROM results;
SELECT AVG(total_points) FROM (SELECT driverId, constructorId, SUM(points) AS total_points FROM results GROUP BY driverId, constructorId);
SELECT SUM(avg_pos * cnt) * 1.0 / SUM(cnt)
FROM (
  SELECT driverId, AVG(position) AS avg_pos, COUNT(*) AS cnt
  FROM qualifying
  GROUP BY driverId
);
